-- 1. CREATE CORE TABLE docs (Real-time synchronized data store)
create table if not exists public.docs (
  col text not null,
  id text not null,
  data jsonb not null default '{}'::jsonb,
  updated_at timestamptz default now(),
  primary key (col, id)
);

-- 2. ENABLE REALTIME BROADCASTING
do $$
begin
  if not exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime' and tablename = 'docs'
  ) then
    alter publication supabase_realtime add table public.docs;
  end if;
end $$;

-- 3. ROW LEVEL SECURITY (Allow read/write for Anon Key)
alter table public.docs enable row level security;
drop policy if exists "Enable all access for anon" on public.docs;
create policy "Enable all access for anon" on public.docs
  for all to anon using (true) with check (true);

-- 4. INSERT ALL DASHBOARD DATA (Users, Leads, Customers, Products, Commissions, Team, etc.)

-- 5. RELATIONAL VIEWS (So you see clean individual tables in Supabase Table Editor!)
create or replace view public.users as
select
  id,
  data->>'name' as name,
  data->>'email' as email,
  data->>'role' as role,
  data->>'title' as title,
  data->>'teamId' as team_id,
  data->>'photo' as photo,
  (data->>'active')::boolean as active,
  data->>'createdAt' as created_at
from public.docs where col = 'users';

create or replace view public.leads as
select
  id,
  data->>'company' as company,
  data->>'contact' as contact,
  data->>'stage' as stage,
  coalesce((data->>'value')::numeric, 0) as expected_mrr,
  data->>'phone' as phone,
  data->>'email' as email,
  data->>'industry' as industry,
  data->>'source' as source,
  data->>'city' as city,
  data->>'createdAt' as created_at,
  data->>'nextFollowUp' as next_follow_up,
  data->>'nextAction' as next_action
from public.docs where col = 'leads';

create or replace view public.customers as
select
  id,
  data->>'business' as business,
  data->>'contact' as contact,
  data->>'status' as status,
  coalesce((data->>'price')::numeric, 0) as monthly_price,
  coalesce((data->>'setupFee')::numeric, 0) as setup_fee,
  data->>'payment' as payment_status,
  data->>'industry' as industry,
  data->>'phone' as phone,
  data->>'email' as email,
  data->>'start' as start_date,
  data->'paidMonths' as paid_months
from public.docs where col = 'customers';

create or replace view public.products as
select
  id,
  data->>'name' as name,
  data->>'type' as type,
  data->>'stage' as stage,
  data->>'status' as status,
  data->>'pricing' as pricing
from public.docs where col = 'products';

create or replace view public.commissions as
select
  id,
  data->>'company' as company,
  coalesce((data->>'amount')::numeric, 0) as commission_amount,
  coalesce((data->>'dealMrr')::numeric, 0) as deal_mrr,
  data->>'rule' as rule,
  data->>'status' as status,
  data->>'wonAt' as won_at
from public.docs where col = 'commissions';

create or replace view public.team as
select
  id,
  data->>'name' as name,
  data->>'role' as role,
  data->>'dept' as department,
  coalesce((data->>'quota')::numeric, 0) as quota,
  data->>'status' as status,
  data->>'email' as email,
  data->>'photo' as photo
from public.docs where col = 'team';

create or replace view public.expenses as
select
  id,
  data->>'desc' as description,
  data->>'category' as category,
  coalesce((data->>'amount')::numeric, 0) as amount,
  data->>'type' as expense_type,
  data->>'date' as expense_date,
  data->>'status' as payment_status
from public.docs where col = 'expenses';
